INSERT INTO meetings (id, batch_id, mentor_id, meeting_number, meeting_date, mode, agenda, discussion, findings, assignment, remarks, status, created_at) VALUES (91, 1, 1, 1, '2026-07-22 10:30:00', 'Offline / Classroom 301', 'Semester Orientation, Mentoring Framework & Academic Goal Setting', 'Welcomed mentees to semester curriculum, reviewed university examination regulations, academic threshold (>75% attendance), and continuous internal evaluation (ISE/MSE).', 'All students verified profile details and enrolled in departmental mentorship program.', 'Complete counseling card entries and register for core technical clubs.', 'Constructive session conducted with high engagement.', 'Completed', '2026-10-15 01:27:14');
INSERT INTO meetings (id, batch_id, mentor_id, meeting_number, meeting_date, mode, agenda, discussion, findings, assignment, remarks, status, created_at) VALUES (92, 1, 1, 2, '2026-08-25 14:00:00', 'Offline / AI & DS Department Lab', 'In-Semester Evaluation (ISE-1), Lab Practicals & August Attendance Review', 'Evaluated performance in ISE-1 unit tests, reviewed practical code submissions, analyzed August monthly attendance reports, identified students needing support.', 'Most mentees maintain healthy attendance above 80%; students with low subject attendance received individual counseling.', 'Submit pending lab journal assignments and verify NPTEL course enrollment.', 'Attendance counseling documented in official mentor log.', 'Completed', '2026-10-15 01:27:14');
INSERT INTO meetings (id, batch_id, mentor_id, meeting_number, meeting_date, mode, agenda, discussion, findings, assignment, remarks, status, created_at) VALUES (93, 1, 1, 3, '2026-09-24 11:30:00', 'Offline / Department Seminar Hall', 'Mid-Semester Examination (MSE) Analysis, Remedial Guidance & Project Progress', 'Detailed review of MSE answer sheets, clarification of complex topics, review of capstone/mini-project milestone 1, internship applications.', 'Identified priority academic intervention areas; scheduled remedial guidance sessions for students needing assistance.', 'Prepare revision problem sets and submit project architecture documents.', 'Remedial action plans established for affected students.', 'Completed', '2026-10-15 01:27:14');
